package in.asmj.ride.web;
import in.asmj.ride.model.*;import in.asmj.ride.repo.*;import in.asmj.ride.service.DocumentRequirementService;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.nio.charset.StandardCharsets;import java.util.*;
@Controller public class AdminOperationsController {
 private final UserAccountRepository users;private final RideBookingRepository rides;private final VehicleRepository vehicles;private final PaymentRecordRepository payments;private final SupportTicketRepository tickets;private final SafetyReportRepository safety;private final RideReviewRepository reviews;private final DocumentRequirementService documentRequirements;
 public AdminOperationsController(UserAccountRepository u,RideBookingRepository r,VehicleRepository v,PaymentRecordRepository p,SupportTicketRepository t,SafetyReportRepository s,RideReviewRepository rv,DocumentRequirementService documentRequirements){users=u;rides=r;vehicles=v;payments=p;tickets=t;safety=s;reviews=rv;this.documentRequirements=documentRequirements;}
 @GetMapping("/admin/operations") public String dashboard(@RequestParam(required=false) String from,@RequestParam(required=false) String to,@RequestParam(required=false) String city,@RequestParam(required=false) String journeyType,Model m){List<RideBooking> all=rides.findAll();java.time.LocalDate fromDate=null,toDate=null;try{if(from!=null&&!from.isBlank())fromDate=java.time.LocalDate.parse(from);}catch(Exception ignored){}try{if(to!=null&&!to.isBlank())toDate=java.time.LocalDate.parse(to);}catch(Exception ignored){}final java.time.LocalDate fd=fromDate,td=toDate;List<RideBooking> filtered=all.stream().filter(r->r.getCreatedAt()!=null&&(fd==null||!r.getCreatedAt().atZone(java.time.ZoneId.systemDefault()).toLocalDate().isBefore(fd))&&(td==null||!r.getCreatedAt().atZone(java.time.ZoneId.systemDefault()).toLocalDate().isAfter(td))).filter(r->city==null||city.isBlank()||city.equals(r.getPickupCity())||city.equals(r.getDestinationCity())).filter(r->journeyType==null||journeyType.isBlank()||journeyType.equals(r.getJourneyType())).toList();Set<String> rideIds=filtered.stream().map(RideBooking::getId).collect(java.util.stream.Collectors.toSet());List<PaymentRecord> ps=payments.findAll().stream().filter(p->rideIds.contains(p.getRideId())).toList();m.addAttribute("customers",users.findByRoleIn(List.of("CUSTOMER")).size());m.addAttribute("partners",users.findByRoleIn(List.of("DRIVER","FLEET_OWNER")).size());m.addAttribute("vehicles",vehicles.count());m.addAttribute("totalRides",filtered.size());m.addAttribute("activeRides",filtered.stream().filter(r->List.of("REQUESTED","ACCEPTED","ASSIGNED","IN_PROGRESS").contains(r.getStatus())).count());m.addAttribute("completedRides",filtered.stream().filter(r->"COMPLETED".equals(r.getStatus())).count());m.addAttribute("cancelledRides",filtered.stream().filter(r->"CANCELLED".equals(r.getStatus())).count());m.addAttribute("oneWayRides",filtered.stream().filter(r->!"ROUND_TRIP".equals(r.getJourneyType())).count());m.addAttribute("roundTrips",filtered.stream().filter(r->"ROUND_TRIP".equals(r.getJourneyType())).count());m.addAttribute("returnPending",filtered.stream().filter(r->"ROUND_TRIP".equals(r.getJourneyType())&&!("COMPLETED".equals(r.getReturnLegStatus())||"CANCELLED".equals(r.getReturnLegStatus()))).count());m.addAttribute("grossPaid",ps.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(PaymentRecord::getGrossAmount).sum());m.addAttribute("commission",ps.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(p->p.getCommissionAmount()+p.getReturnCommissionAmount()).sum());m.addAttribute("unsettled",ps.stream().filter(p->"PAID".equals(p.getStatus())).mapToDouble(p->(!p.isSettled()?p.getDriverNetAmount():0)+(!p.isReturnSettled()?p.getReturnDriverNetAmount():0)).sum());m.addAttribute("openTickets",tickets.findAll().stream().filter(t->!List.of("RESOLVED","CLOSED").contains(t.getStatus())).count());m.addAttribute("openSafety",safety.findAll().stream().filter(s->!List.of("RESOLVED","CLOSED").contains(s.getStatus())).count());m.addAttribute("from",from==null?"":from);m.addAttribute("to",to==null?"":to);m.addAttribute("city",city==null?"":city);m.addAttribute("journeyType",journeyType==null?"":journeyType);m.addAttribute("cityOptions",all.stream().flatMap(r->java.util.stream.Stream.of(r.getPickupCity(),r.getDestinationCity())).filter(Objects::nonNull).distinct().sorted().toList());Map<String,Long> cityRideCounts=filtered.stream().flatMap(r->java.util.stream.Stream.of(r.getPickupCity(),r.getDestinationCity())).filter(x->x!=null&&!x.isBlank()).collect(java.util.stream.Collectors.groupingBy(x->x,java.util.stream.Collectors.counting()));m.addAttribute("cityRideCounts",cityRideCounts);return "admin-operations";}
 @GetMapping("/admin/users") public String users(Model m){m.addAttribute("users",users.findAll());return "admin-users";}
 @PostMapping("/admin/users/{id}/status") public String userStatus(@PathVariable String id,@RequestParam String status){UserAccount u=users.findById(id).orElseThrow();if("ADMIN".equals(u.getRole())||!List.of("APPROVED","PENDING","REJECTED","SUSPENDED").contains(status))return "redirect:/admin/users?error";if("APPROVED".equals(status)&&!documentRequirements.verifiedUserDocuments(u))return "redirect:/admin/users?documentsRequired";u.setStatus(status);if("SUSPENDED".equals(status))u.setAvailable(false);users.save(u);return "redirect:/admin/users?updated";}
 @GetMapping("/admin/safety") public String safety(Model m){m.addAttribute("reports",safety.findAllByOrderByCreatedAtDesc());return "admin-safety";}
 @GetMapping("/admin/reviews") public String reviews(Model m){m.addAttribute("reviews",reviews.findAllByOrderByCreatedAtDesc());return "admin-reviews";}
 @GetMapping("/admin/operations/export") @ResponseBody public ResponseEntity<byte[]> export(@RequestParam(required=false) String from,@RequestParam(required=false) String to,@RequestParam(required=false) String city,@RequestParam(required=false) String journeyType){java.time.LocalDate fd=null,td=null;try{if(from!=null&&!from.isBlank())fd=java.time.LocalDate.parse(from);}catch(Exception ignored){}try{if(to!=null&&!to.isBlank())td=java.time.LocalDate.parse(to);}catch(Exception ignored){}final java.time.LocalDate f=fd,t=td;List<RideBooking> selected=rides.findAll().stream().filter(r->r.getCreatedAt()!=null&&(f==null||!r.getCreatedAt().atZone(java.time.ZoneId.systemDefault()).toLocalDate().isBefore(f))&&(t==null||!r.getCreatedAt().atZone(java.time.ZoneId.systemDefault()).toLocalDate().isAfter(t))).filter(r->city==null||city.isBlank()||city.equals(r.getPickupCity())||city.equals(r.getDestinationCity())).filter(r->journeyType==null||journeyType.isBlank()||journeyType.equals(r.getJourneyType())).toList();Map<String,PaymentRecord> paymentByRide=new HashMap<>();payments.findAll().forEach(p->paymentByRide.put(p.getRideId(),p));StringBuilder csv=new StringBuilder("Ride ID,Created,Customer,Mobile,Pickup City,Pickup PIN,Destination City,Destination PIN,Journey,Outward Status,Return Status,Outward Driver,Return Driver,Vehicle,Return Vehicle,Estimated Fare,Final Fare,Payment Method,Payment Status\n");for(RideBooking r:selected){PaymentRecord p=paymentByRide.get(r.getId());csv.append(csv(r.getId())).append(',').append(csv(String.valueOf(r.getCreatedAt()))).append(',').append(csv(r.getCustomerName())).append(',').append(csv(r.getCustomerMobile())).append(',').append(csv(r.getPickupCity())).append(',').append(csv(r.getPickupPinCode())).append(',').append(csv(r.getDestinationCity())).append(',').append(csv(r.getDestinationPinCode())).append(',').append(csv(r.getJourneyType())).append(',').append(csv(r.getStatus())).append(',').append(csv(r.getReturnLegStatus())).append(',').append(csv(r.getAssignedDriverName())).append(',').append(csv(r.getReturnAssignedDriverName())).append(',').append(csv(r.getAssignedVehicleNumber())).append(',').append(csv(r.getReturnAssignedVehicleNumber())).append(',').append(r.getEstimatedFare()).append(',').append(r.getFinalFare()).append(',').append(csv(r.getPaymentMethod())).append(',').append(csv(p==null?"NOT_SUBMITTED":p.getStatus())).append('\n');}HttpHeaders headers=new HttpHeaders();headers.setContentType(new MediaType("text","csv",StandardCharsets.UTF_8));headers.setContentDisposition(ContentDisposition.attachment().filename("asmj-ride-operations.csv").build());return new ResponseEntity<>(csv.toString().getBytes(StandardCharsets.UTF_8),headers,HttpStatus.OK);}
 private String csv(String value){if(value==null)return "\"\"";String safe=value.matches("^[=+@\\-].*")?"\'"+value:value;return "\""+safe.replace("\"","\"\"")+"\"";}

}
